-- BattleBallServer: achievements (reward = an avatar skin or gems). GENERATED by BattleBall/SourceData/tools/build_achievement_seed_sql.py.
-- Status: PROPOSED. Owner decision 2026-10-07: avatars outside the race starters are obtained through achievements (option B).
-- The conditions below (reach a character level) are my proposal; the admin page edits thresholds, rewards and enabled flags.
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

CREATE TABLE IF NOT EXISTS achievement_template (
  achievement_id   INT UNSIGNED NOT NULL,
  name_vi          VARCHAR(120) NOT NULL,
  race             ENUM('EARTH','NAMEC','XAYDA','ANY') NOT NULL DEFAULT 'ANY',  -- which character can earn it
  condition_type   ENUM('LEVEL_REACH','WINS_TOTAL','FIRST_CLEAR_BOSS') NOT NULL,
  threshold        INT UNSIGNED NOT NULL,                -- level / number of wins / boss id
  reward_costume_id INT UNSIGNED NULL,                   -- skin granted (owned_skin.source = 'REWARD')
  reward_gems      INT UNSIGNED NULL,
  enabled          TINYINT(1)   NOT NULL DEFAULT 1,
  updated_at       TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  updated_by       VARCHAR(64)  NULL,
  PRIMARY KEY (achievement_id),
  KEY idx_ach_cond (condition_type, enabled),
  CONSTRAINT fk_ach_skin FOREIGN KEY (reward_costume_id) REFERENCES skin_template (costume_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS character_achievement (
  character_id   BIGINT UNSIGNED NOT NULL,
  achievement_id INT UNSIGNED    NOT NULL,
  completed_at   TIMESTAMP       NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (character_id, achievement_id),
  CONSTRAINT fk_cach_char FOREIGN KEY (character_id)   REFERENCES game_character (character_id) ON DELETE CASCADE,
  CONSTRAINT fk_cach_ach  FOREIGN KEY (achievement_id) REFERENCES achievement_template (achievement_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

SET FOREIGN_KEY_CHECKS = 1;

